async function apiJSON(response){
 const text=await response.text();
 const auth=response.status===401||response.status===403||response.redirected&&/signin|login|callback/.test(response.url);
 if(auth){if($('signIn'))$('signIn').hidden=false;throw Error('입장이 만료됐습니다. 돌아가기에서 비밀번호로 다시 입장하세요.');}
 if(!/application\/json|\+json/i.test(response.headers.get('content-type')||'')){
 const html=/^\s*(?:<!doctype|<html|<)/i.test(text);
 if(html&&$('signIn'))$('signIn').hidden=false;
 throw Error(response.status===404?'API 주소를 찾지 못했습니다. 페이지를 새로고침해주세요.':html?'서버 응답을 확인할 수 없습니다. 돌아가기에서 다시 입장하세요.':'서버 응답 형식이 올바르지 않습니다. 잠시 후 다시 시도해주세요.');
 }
 try{return JSON.parse(text)}catch{throw Error('서버의 데이터 응답을 해석하지 못했습니다. 잠시 후 다시 시도해주세요.')}
}
async function pushState(){if(saving||!ready||conflict)return;saving=true;pending=false;const snapshot=JSON.stringify(s);status('DB 저장 중…');try{const r=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,state:JSON.parse(snapshot)})});const data=await apiJSON(r);if(!r.ok){if(r.status===409)conflict=true;throw Error(data.error)}revision=data.revision;status('DB 저장 완료 · '+new Date().toLocaleTimeString('ko-KR'));}catch(e){status(e.message);pending=true;}finally{saving=false;if(pending&&!conflict&&JSON.stringify(s)!==snapshot)saveTimer=setTimeout(pushState,500)}}
async function loadState(){$('sharedSheet').hidden=true;$('sharedSheet').removeAttribute('href');$('sheetConnect').hidden=true;sheetConnection=null;if(saving){alert('저장이 끝난 뒤 다시 시도하세요.');return}if(pending&&!confirm('아직 DB에 저장되지 않은 수정 내용이 있습니다. 다시 불러오면 덮어씁니다. 계속할까요?'))return;clearTimeout(saveTimer);loading=true;ready=false;$('dashboard').inert=true;status('DB 연결 중…');try{const r=await fetch('/api/state');const data=await apiJSON(r);if(!r.ok)throw Error(data.error);revision=data.revision;conflict=false;pending=false;s=data.state||initial();renderInputs();status(data.state?'DB 불러오기 완료':(workspaceId==='legacy'?'DB 연결 완료 · 예시 데이터':'새 길드 공간 · 명단부터 등록하세요.'));$('migrate').hidden=!legacy||!platformAdmin;$('migration').textContent=legacy&&platformAdmin?'예전 브라우저에 저장한 데이터가 있습니다. 가져오기 버튼은 현재 DB 내용을 교체합니다.':'';ready=true;await loadPrices();await loadActivities()}catch(e){status(e.message+' 백업은 저장할 수 있습니다.')}finally{loading=false;$('dashboard').inert=false}}
async function loadPrices(){try{const r=await fetch('/api/prices'),d=await apiJSON(r);if(!r.ok)throw Error(d.error);const catalogChanged=JSON.stringify(catalog)!==JSON.stringify(d.catalog),wasReady=pricesReady;catalog=d.catalog;pricesReady=true;
 const requestSelected=$('priceRequestItem').value;$('priceRequestItem').innerHTML=catalog.map(p=>`<option value="${esc(p.item_id)}">${esc(p.item_name)}</option>`).join('');if(requestSelected)$('priceRequestItem').value=requestSelected;const selected=$('priceTarget').value;$('priceTarget').innerHTML='<option value="">새 아이템 등록</option>'+catalog.map(p=>`<option value="${esc(p.item_id)}">${esc(p.item_name)}</option>`).join('');$('priceTarget').value=selected;
 renderCatalog();
 $('priceHistory').innerHTML=d.prices.length?'<table><thead><tr><th>조사일</th><th>아이템</th><th>블다/개</th><th>메모</th></tr></thead><tbody>'+d.prices.map(p=>`<tr><td>${esc(shortObserved(p.observed_at))}</td><td>${esc(p.item_name)}</td><td>${fmt(Math.round(Number(p.unit_price)))}</td><td>${esc(p.note)}</td></tr>`).join('')+'</tbody></table>':'아직 기록한 시세가 없습니다.';
 const before=JSON.stringify(s.items);s.items=applyMarketPrices(s.items,catalog);if(catalogChanged||before!==JSON.stringify(s.items)||!wasReady)renderInputs();return true;
 }catch(e){pricesReady=false;$('priceStatus').textContent=e.message;return false}}
function filterValues(scope){const v={};for(const key of ['q','type','grade','category','enhance','optionGrade','optionText','potentialGrade','potentialSkill','part','recipeType','tradeCount','registerable','soulSkillGrade','enhanceMin','enhanceMax'])v[key]=$('filter-'+scope+'-'+key)?.value||'';return v;}
function shortObserved(value){const date=new Date(value);if(!Number.isFinite(date.getTime()))return '—';const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);const get=k=>parts.find(p=>p.type===k)?.value;return `${get('month')}/${get('day')} ${get('hour')}:${get('minute')}`;}
function renderCatalog(){$('priceAdminLogin').hidden=platformAdmin;renderMarketTabs();const list=catalog.filter(p=>matchesItem(p,{...filterValues('catalog'),marketGroup:marketTab==='기타'?'':marketTab})&&(marketTab!=='기타'||!['장비','레시피','징표','냥혼석'].includes(inferredAttributes(p.item_name,p.attributes||{}).marketGroup)));$('catalogCount').textContent=list.length+' / '+catalog.length+'개 표시';
 $('priceCatalog').innerHTML=list.length?'<table><thead><tr><th>아이템</th><th>블다/개</th><th>조사 시각</th><th></th></tr></thead><tbody>'+list.map(p=>{const a=p.attributes||{};return `<tr><td>${esc(p.item_name)}</td><td>${platformAdmin&&!String(p.item_id).startsWith('shared-')?`<input type="number" min="1" step="1" aria-label="${esc(p.item_name)} 시세" data-catalog-price="${esc(p.item_id)}" value="${Math.round(Number(p.unit_price))}">`:fmt(Math.round(Number(p.unit_price)))}</td><td>${esc(shortObserved(p.observed_at))}</td><td>${platformAdmin&&!String(p.item_id).startsWith('shared-')?`<button data-save-catalog-price="${esc(p.item_id)}">시세 저장</button>`:''} ${platformAdmin?`<button data-edit-catalog="${esc(p.item_id)}">분류·옵션 수정</button>`:`<button data-request-price="${esc(p.item_id)}">시세 수정 요청</button>`} <button data-add-catalog="${esc(p.item_id)}">창고에 추가</button></td></tr>`}).join('')+'</tbody></table>':'조건에 맞는 아이템이 없습니다.';
}
function specText(a={}){return [...(a.options||[]).map(o=>o.grade+' '+o.text),a.potential?.grade||a.potential?.skill?'잠재 '+(a.potential?.grade||'')+' '+(a.potential?.skill||''):''].filter(Boolean).join(' / ')}
function calculate(state,records=activityRecords){if(!pricesReady&&state.items.some(i=>i.qty>0&&(valuationMethod(i)==='catalog'||valuationMethod(i)==='expected'&&i.rewardRecipe?.rewards.some(r=>r.catalogId))))throw Error('시세 DB를 새로고침한 뒤 분배하세요.');if(records===activityRecords&&!activitiesReady&&state.items.some(i=>i.qty>0&&['siege','race'].includes(i.basis)))throw Error('활동 DB를 불러온 뒤 분배하세요.');return allocate(state,records)}
function renderInputs(){s.members=s.members.map(m=>({...m,trophyMode:'manual'}));s.items=s.items.map(i=>({...i,price:roundUnitPrice(i.price)}));unifyBattlegroundRewards(s);renderContentTrophies();renderBattleRecords();renderGuild();s.rates??={capture:1,defense:1,race:1}; $('period').value=s.period;$('equal').value=s.equal;$('minimum').value=s.minimum;
 $('members').innerHTML=s.members.map(m=>`<tr data-member="${m.id}"><td><input aria-label="${esc(m.name)} 분배 대상" type="checkbox" data-field="active" ${m.active?'checked':''}></td><td><input aria-label="닉네임" type="text" data-field="name" value="${esc(m.name)}"></td><td><input aria-label="기록용 주간 트로피" type="number" min="0" step="1" data-field="t" value="${m.t}"></td><td><input aria-label="총 기여도" type="number" min="0" step="1" data-field="totalContribution" value="${m.totalContribution??''}"></td><td><input aria-label="이월 블다" type="number" data-field="carry" value="${m.carry}"></td><td><button data-delete-member="${m.id}" aria-label="길드원 삭제">×</button></td></tr>`).join('');
 $('inventoryCount').textContent=s.items.filter(i=>(!settledItem(s,i)||$('showSettled').checked)&&matchesItem(i,filterValues('inventory'))).length+' / '+s.items.length+'개 표시';
 $('items').innerHTML=s.items.filter(i=>(!settledItem(s,i)||$('showSettled').checked)&&matchesItem(i,filterValues('inventory'))).map(i=>`<tr data-item="${i.id}"><td><input type="text" aria-label="아이템 이름" data-field="name" value="${esc(i.name)}" ></td><td><select aria-label="분배 방식" data-field="kind"><option value="market" ${i.kind==='market'?'selected':''}>블다 가치 분배</option><option value="pool" ${i.kind==='pool'?'selected':''}>종류별 분배</option></select></td><td><select aria-label="재화 분배 기준" data-field="basis" >${Object.entries(basisName).filter(([b])=>!['trophy','event'].includes(b)).map(([v,n])=>`<option value="${v}" ${(i.basis||'trophy')===v?'selected':''}>${n}</option>`).join('')}</select>${['battleEqual','battleScore'].includes(i.basis)?`<select aria-label="보상 출처 몬스터" data-field="battleId"><option value="">몬스터 기록 선택</option><option value="all" ${i.battleId==='all'?'selected':''}>전체 기록 · 합산</option>${(s.battleRuns||[]).map(r=>`<option value="${esc(r.id)}" ${i.battleId===r.id?'selected':''}>${esc(battleZones[r.zone]+' · '+(r.date?r.date+' · ':'')+r.name+(r.guildRank?' · 길드 '+r.guildRank+'위':''))}</option>`).join('')}</select>`:''}</td><td><input aria-label="창고 수량" type="number" min="0" max="100000" data-field="qty" value="${i.qty}"></td><td><input aria-label="개당 블다 가격" type="number" min="0" step="any" data-field="price" value="${i.price}" ${valuationMethod(i)!=='manual'?'disabled':''}></td><td><select data-field="valuation" aria-label="블다 가치 평가"><option value="manual" ${valuationMethod(i)==='manual'?'selected':''}>수동 단가</option><option value="catalog" ${valuationMethod(i)==='catalog'?'selected':''}>시세 DB 연동</option><option value="expected" ${valuationMethod(i)==='expected'?'selected':''}>보상 기대값</option></select></td><td><select data-field="catalogId" aria-label="시세 DB 연결" ${valuationMethod(i)==='expected'?'disabled':''}><option value="">연결 안 함</option>${catalog.map(p=>`<option value="${esc(p.item_id)}" ${i.catalogId===p.item_id?'selected':''}>${esc(p.item_name)}</option>`).join('')}</select></td><td><button data-delete-item="${i.id}" aria-label="아이템 삭제">×</button></td></tr>`).join('');renderActivities();update();}
function table(p,items){return `<table><thead><tr><th>길드원</th><th>길드 레이스 포인트</th><th>기록용 길드 트로피</th>${contentBases.filter(b=>items.some(i=>i.basis===b)).map(b=>`<th>${basisName[b]} 트로피</th>`).join('')}<th>이번 권리 (블다)</th>${items.map(i=>`<th>${esc(i.name)}${separateAllocation(i)?' · '+basisName[i.basis||'trophy']:''}</th>`).join('')}<th>지급 가치</th><th>다음 이월 블다 (합계)</th></tr></thead><tbody>${p.rows.map(r=>`<tr><td>${esc(r.member.name)}</td><td>${r.points?fmt(r.points.race):'—'}</td><td>${fmt(r.member.enteredT??r.member.t)}</td>${contentBases.filter(b=>items.some(i=>i.basis===b)).map(b=>`<td>${fmt(contentTrophy(r.member,b))}</td>`).join('')}<td>${fmt(r.target)}</td>${items.map(i=>`<td>${r.qty[i.id]||0}${separateAllocation(i)?`<small title="다음 회차 이월 개수"> (이월 ${fmt(r.pools[poolKey(i)]||0)})</small>`:''}</td>`).join('')}<td>${fmt(r.paid)}</td><td>${fmt(r.deficit)}</td></tr>`).join('')}</tbody></table>`}
function update(){applyWorkspacePermissions();renderPayoutSelection();renderDistributionControls();renderGuild();plan=null;$('error').textContent='';try{if(selectedItems(s).length){plan=calculate({...s,items:selectedItems(s),payoutSelection:'all'});$('results').innerHTML=table(plan,selectedItems(s))}else{$('results').innerHTML='<p class="empty-state">현재 지급할 창고 아이템이 없습니다.</p>'}}catch(e){$('error').textContent=e.message;$('results').innerHTML=''}$('confirm').disabled=!plan||!selectedItems(s).some(i=>i.qty>0);$('csv').disabled=!plan; const stat=(a,b)=>`<div class="stat"><span>${a}</span><strong>${b}</strong></div>`;$('stats-guild').innerHTML=stat('분배 대상',s.members.filter(m=>m.active).length+'명')+stat('주간 트로피',fmt(s.members.reduce((a,m)=>a+(contribution(m).weekly||0),0)));$('stats-payout').innerHTML=stat('지급 대상',plan?plan.rows.length+'명':'—')+stat('선택한 보상 가치',plan?fmt(plan.value)+' 블다':'—');$('stats-inventory').innerHTML=stat('창고 총 가치',fmt(s.items.reduce((a,i)=>a+i.qty*i.price,0))+' 블다')+stat('보유 아이템',s.items.filter(i=>i.qty>0).length+'종');$('history').innerHTML=s.history.length?s.history.slice().reverse().map(h=>`<details><summary>${esc(h.period)} · ${h.plan.rows.length}명 · ${fmt(h.plan.value)} 블다</summary><div class="scroll">${table(h.plan,h.items)}</div></details>`).join(''):'아직 확정한 정산이 없습니다.';$('undo').disabled=!s.history.length;save();applyWorkspacePermissions()}
document.addEventListener('change',e=>{let el=e.target,row=el.closest('[data-member],[data-item]');if(row&&el.dataset.field){let obj=row.dataset.member?s.members.find(m=>m.id===row.dataset.member):s.items.find(i=>i.id===row.dataset.item);if(row.dataset.member&&el.dataset.field==='totalContribution'){const value=el.value.trim()===''?null:Number(el.value);if(value!==null&&(!Number.isSafeInteger(value)||value<0)){alert('총 기여도는 0 이상의 정수로 입력하세요.');renderInputs();return}obj.totalContribution=value;obj.totalObservedAt=new Date().toISOString();update();return}if(row.dataset.item&&['catalogId','valuation'].includes(el.dataset.field)){if(el.dataset.field==='valuation'&&el.value==='expected'){activateTab('prices');showSub('prices','rewards');openRewardEditor(obj.id);renderInputs();return}const candidate={...obj,[el.dataset.field]:el.value};if(el.dataset.field==='catalogId')candidate.valuation=el.value?'catalog':'manual';if(candidate.valuation==='catalog'&&!candidate.catalogId){alert('옆의 시세 DB 연결에서 아이템을 선택하세요.');renderInputs();return}try{Object.assign(obj,resolveItemValue(candidate,catalog));renderInputs()}catch(err){alert(err.message);renderInputs()}return}const oldPoolKey=row.dataset.item?poolKey(obj):null;if(row.dataset.item&&el.dataset.field==='price')el.value=roundUnitPrice(Number(el.value));obj[el.dataset.field]=el.dataset.field==='minimumPerParticipant'?(el.checked?1:0):el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(row.dataset.item&&['basis','battleId'].includes(el.dataset.field)){const nextPoolKey=poolKey(obj);if(oldPoolKey!==nextPoolKey)for(const m of s.members){if(Object.hasOwn(m.pools,oldPoolKey)){m.pools[nextPoolKey]=(m.pools[nextPoolKey]||0)+m.pools[oldPoolKey];delete m.pools[oldPoolKey]}}}if(el.dataset.field==='catalogId'&&obj.catalogId){s.items=applyMarketPrices(s.items,catalog);}if(['kind','basis','battleId','minimumPerParticipant','catalogId','trophyMode','t'].includes(el.dataset.field))renderInputs();else update()}if(['period','equal','minimum'].includes(el.id)){s[el.id]=el.id==='period'?el.value:Number(el.value);renderActivities();update()}});
document.addEventListener('click',e=>{const m=e.target.dataset.deleteMember,i=e.target.dataset.deleteItem;if(m&&confirm('길드원을 삭제하면 해당 인원의 이월도 삭제됩니다. 삭제할까요?')){s.members=s.members.filter(x=>x.id!==m);renderInputs()}if(i&&confirm('아이템을 삭제하면 해당 종류의 이월 연결도 사라집니다. 수량을 0으로 두면 유지됩니다. 삭제할까요?')){s.items=s.items.filter(x=>x.id!==i);renderInputs()}});
$('addMember').onclick=()=>{s.members.push({id:uid(),name:'새 길드원 '+(s.members.length+1),t:0,carry:0,active:true,pools:{}});renderInputs()};$('addItem').onclick=()=>{s.items.push({id:uid(),name:'새 아이템 '+(s.items.length+1),kind:'pool',qty:0,price:0});renderInputs()};$('pasteAdd').onclick=()=>{const lines=$('paste').value.trim().split('\n').filter(Boolean).map(l=>l.split(/[\t,]/));if(lines.some(a=>a.length!==2||!a[0].trim()||!Number.isFinite(Number(a[1]))||Number(a[1])<0)){alert('닉네임,트로피 형식으로 입력하세요.');return}lines.forEach(([name,t])=>s.members.push({id:uid(),name:name.trim(),t:Number(t),carry:0,active:true,pools:{}}));$('paste').value='';renderInputs()};
