function renderActivities(){if(!$('activityMember'))return;const current=$('activityMember').value;$('activityMember').innerHTML=s.members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('');if(s.members.some(m=>m.id===current))$('activityMember').value=current;for(const type of ['capture','defense'])$('rate-'+type).value=s.rates?.[type]||1;const totals=activityTotals(s,activityRecords);$('activitySummary').innerHTML='<p>레이스 회차 '+activityPeriod(s,'race')+' · 점령전 회차 '+activityPeriod(s,'capture')+'</p><table><thead><tr><th>닉네임</th><th>점령 포인트</th><th>방어 포인트</th><th>레이스 포인트</th></tr></thead><tbody>'+s.members.map(m=>{const t=totals[m.id]||{capture:0,defense:0,race:0};return `<tr><td>${esc(m.name)}</td><td>${fmt(t.capture)}</td><td>${fmt(t.defense)}</td><td>${fmt(t.race)}</td></tr>`}).join('')+'</tbody></table>';$('activityLog').innerHTML='<table><thead><tr><th>회차</th><th>닉네임</th><th>활동</th><th>횟수</th><th>회당 점수 / 미션 포인트</th><th>포인트</th><th>메모</th><th>상태</th></tr></thead><tbody>'+activityRecords.map(r=>`<tr><td>${esc(r.period)}</td><td>${esc(s.members.find(m=>m.id===r.member_id)?.name||r.member_name)}</td><td>${activityName[r.activity]}</td><td>${r.count}</td><td>${r.unit_points}</td><td>${fmt(r.points)}</td><td>${esc(r.note)}</td><td>${r.voided?'취소됨':`<button data-void="${esc(r.id)}">취소</button>`}</td></tr>`).join('')+'</tbody></table>'}
