let sheetChecking=false,sheetConnection=null;
async function checkSheet(retry=false){
 if(sheetChecking||!ready)return;sheetChecking=true;
 const button=$('sheetRetry');button.disabled=true;
 try{if(retry)$('sheetStatus').textContent='구글시트 동기화 중…';const checkedGuild=workspaceId;const r=await fetch('/api/sync',retry?{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}:{}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);if(checkedGuild!==workspaceId)return;
 sheetConnection=d;$('sharedSheet').hidden=!d.sheetUrl;if(d.sheetUrl)$('sharedSheet').href=d.sheetUrl;else $('sharedSheet').removeAttribute('href');$('sheetConnect').hidden=!d.canConfigure;
 if(!retry&&workspaceRole!=='viewer'&&d.configured&&d.pending&&!d.running&&!d.error){sheetChecking=false;await checkSheet(true);return}
 $('sheetStatus').textContent=!d.configured?(d.message||'구글시트 연결이 설정되지 않았습니다.'):d.error?'시트 동기화 실패 · '+d.error:d.running?'구글시트 반영 중…':d.pending?'구글시트 반영 대기 · 동기화 버튼으로 재시도하세요.':'구글시트 동기화 완료 · '+new Date(d.lastSuccess).toLocaleString('ko-KR');
 }catch(e){$('sheetStatus').textContent=e.message}finally{sheetChecking=false;button.disabled=false}
}
$('sheetRetry').onclick=()=>checkSheet(true);
$('sheetConnect').onclick=()=>{$('sheetUrl').value=sheetConnection?.sheetUrl||'';$('sheetAccount').textContent=sheetConnection?.serviceAccount||'서비스 계정이 설정되지 않았습니다.';$('sheetConnectStatus').textContent='';$('sheetDialog').showModal()};
$('sheetClose').onclick=()=>$('sheetDialog').close();
$('sheetConnectSave').onclick=async()=>{const b=$('sheetConnectSave');b.disabled=true;try{const r=await fetch('/api/sync',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:$('sheetUrl').value.trim()})}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);$('sheetConnectStatus').textContent='연결 저장 완료. 하단의 구글시트 동기화 버튼으로 반영하세요.';await checkSheet()}catch(e){$('sheetConnectStatus').textContent=e.message}finally{b.disabled=false}};
