function guild(){s.guild??={name:'',master:'',deputy:'',memberCount:null,level:null,exp:0,requirements:{}};s.guild.requirements??={};return s.guild;}
function renderGuild(){
 $('guild-roster').innerHTML=s.members.map(m=>`<option value="${esc(m.name)}"></option>`).join('');
 const g=guild(),p=guildProgress(g);g.level=p.level;g.exp=p.exp;
 for(const f of ['name','master','deputy','memberCount','level','exp'])$('guild-'+f).value=g[f]??'';
 $('guild-count').textContent='명단 등록 '+s.members.length+'명'+(g.memberCount!=null&&g.memberCount!==s.members.length?' · 게임 인원과 명단이 다릅니다.':'');
 $('guild-growth').textContent=p.level===null?'게임의 현재 길드 레벨과 경험치를 입력하세요.':p.next?'Lv. '+p.level+' · '+fmt(p.exp)+' / '+fmt(p.next)+' EXP · 다음 레벨까지 '+fmt(p.remaining)+' EXP':'Lv. '+p.level+' · '+fmt(p.exp)+' EXP · 이 레벨의 필요 경험치 기준이 없습니다.';
 $('guild-progress').hidden=p.percent===null;$('guild-progress').value=p.percent||0;
 $('level-table').innerHTML=Object.entries(g.requirements).sort((a,b)=>Number(a[0])-Number(b[0])).map(([l,r])=>`<tr><td>${l} → ${Number(l)+1}</td><td>${fmt(r.exp)}</td><td>${esc(r.source)}</td><td><button data-delete-level="${l}">삭제</button></td></tr>`).join('')||'<tr><td colspan="4">확인한 기준이 없습니다. 게임 화면의 필요 경험치를 등록하세요.</td></tr>';
}
for(const f of ['name','master','deputy','memberCount','level','exp'])$('guild-'+f).addEventListener('change',e=>{
 const g=guild(),v=e.target.value;const numeric=['memberCount','level','exp'].includes(f),n=numeric?(v===''&&f!=='exp'?null:Number(v)):v;
 if(numeric&&n!==null&&(!Number.isSafeInteger(n)||n<(f==='level'?1:0)||(f==='level'&&n>10000))){alert('올바른 정수 값을 입력하세요.');renderGuild();return}g[f]=n;renderGuild();save();
});
$('guild-exp-add').onclick=()=>{const n=Number($('guild-exp-gain').value),g=guild();if(!Number.isSafeInteger(n)||n<=0||!Number.isSafeInteger(g.exp+n)){alert('추가 경험치는 양의 정수로 입력하세요.');return}g.exp+=n;renderGuild();$('guild-exp-gain').value='';save()};
$('level-save').onclick=()=>{const level=Number($('level-number').value),exp=Number($('level-needed').value),source=$('level-source').value.trim();if(!Number.isSafeInteger(level)||level<1||level>=10000||!Number.isSafeInteger(exp)||exp<=0||!source){alert('현재 레벨, 필요 경험치, 확인 출처를 입력하세요.');return}guild().requirements[level]={exp,source,checkedAt:new Date().toISOString()};renderGuild();save()};
