function activateTab(id,focus=false){document.querySelectorAll('[data-tab]').forEach(b=>{const selected=b.dataset.tab===id;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;if(selected&&focus)b.focus()});document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==id);}
document.querySelectorAll('[data-tab]').forEach(b=>{b.onclick=()=>activateTab(b.dataset.tab);b.onkeydown=e=>{const buttons=[...document.querySelectorAll('[data-tab]')],i=buttons.indexOf(b);let n;if(e.key==='ArrowRight')n=(i+1)%buttons.length;if(e.key==='ArrowLeft')n=(i+buttons.length-1)%buttons.length;if(e.key==='Home')n=0;if(e.key==='End')n=buttons.length-1;if(n!==undefined){e.preventDefault();activateTab(buttons[n].dataset.tab,true)}}});
