function attrTypeChanged(){const type=$('attr-type').value,old=$('attr-grade').value;const grades=type==='장비'?equipmentGrades:type==='잡화'?miscGrades:[];$('attr-grade').innerHTML='<option value="">미등록</option>'+grades.map(v=>`<option>${v}</option>`).join('');if(grades.includes(old))$('attr-grade').value=old;const gear=type==='장비';$('gear-attributes').hidden=!gear;for(const id of ['attr-category','attr-enhance']){$(id).disabled=!gear;if(!gear)$(id).value='';}}
