function readAttributes(){const gear=$('attr-type').value==='장비',options=[];if(gear)for(let i=0;i<3;i++){const grade=$('attr-option-grade-'+i).value,text=$('attr-option-text-'+i).value;if(grade||text)options.push({grade,text})}return normalizeAttributes({marketGroup:$('attr-marketGroup').value,part:$('attr-part').value,recipeType:$('attr-recipeType').value,tradeCount:$('attr-tradeCount').value===''?null:Number($('attr-tradeCount').value),registerable:$('attr-registerable').value===''?null:$('attr-registerable').value==='yes',soulSkillGrade:$('attr-soulSkillGrade').value,type:$('attr-type').value,grade:$('attr-grade').value,category:gear?$('attr-category').value:'',enhance:gear&&$('attr-enhance').value!==''?Number($('attr-enhance').value.slice(1)):null,options,potential:{grade:gear?$('attr-potential-grade').value:'',skill:gear?$('attr-potential-skill').value:''}})}
