function mountFilters(scope,target){const select=(key,label,values)=>`<label>${label}<select id="filter-${scope}-${key}"><option value="">전체</option>${values.map(v=>`<option value="${v}">${['enhance','enhanceMin','enhanceMax'].includes(key)?'+'+v:v==='yes'?'가능':v==='3+'?'3 이상':v}</option>`).join('')}</select></label>`;$(target).innerHTML=`<label>검색<input id="filter-${scope}-q" type="search" placeholder="이름·옵션·스킬·메모"></label>`+select('part','장비 부위',equipmentParts)+select('recipeType','레시피 종류',['유물','기타'])+select('tradeCount','거래 가능 횟수',[0,1,2,'3+'])+select('registerable','등록 가능 레시피',['yes'])+select('soulSkillGrade','냥혼석 스킬1 등급',['일반','고급','희귀','영웅','전설','신화'])+select('enhanceMin','최소 강화',Array.from({length:10},(_,i)=>i))+select('enhanceMax','최대 강화',Array.from({length:10},(_,i)=>i))+select('type','분류',[...itemTypes,'미분류'])+select('grade','등급',[...new Set([...equipmentGrades,...miscGrades])])+select('category','카테고리',categories)+select('enhance','강화',Array.from({length:10},(_,i)=>i))+select('optionGrade','추가옵션 등급',optionGrades)+`<label>추가옵션 검색<input id="filter-${scope}-optionText" type="search"></label>`+select('potentialGrade','잠재능력 등급',potentialGrades)+`<label>잠재 스킬 검색<input id="filter-${scope}-potentialSkill" type="search"></label><button id="filter-${scope}-reset">초기화</button>`;const container=$(target);if(scope==='inventory'){container.querySelectorAll('label').forEach(label=>{if(!label.querySelector('[id$="-q"]'))label.remove()});container.querySelector('input').placeholder='아이템 이름 검색';}else{const primary=new Set(['q','grade','category','part','recipeType','soulSkillGrade']);const details=document.createElement('details');details.className='advanced-filters';details.innerHTML='<summary>상세 필터</summary><div class="filter-grid"></div>';const grid=details.lastElementChild;container.querySelectorAll('label').forEach(label=>{const key=label.querySelector('input,select').id.replace('filter-catalog-','');if(!primary.has(key))grid.append(label)});details.remove();};const refresh=()=>{filtering=true;try{scope==='catalog'?renderCatalog():renderInputs()}finally{filtering=false}};$(target).querySelectorAll('input,select').forEach(el=>el.addEventListener('input',refresh));$('filter-'+scope+'-reset').onclick=()=>{$(target).querySelectorAll('input,select').forEach(el=>el.value='');refresh()};}
mountFilters('catalog','catalogFilters');mountFilters('inventory','inventoryFilters');renderCatalog();



let rewardEditing=null,rewardDraft=null;
function rewardOptions(selected){return '<option value="">수동 단가</option>'+catalog.map(p=>`<option value="${esc(p.item_id)}" ${selected===p.item_id?'selected':''}>${esc(p.item_name)}</option>`).join('')}
function collectRewardDraft(){if(!rewardDraft)return;rewardDraft.mode=$('rewardMode').value;rewardDraft.rewards=[...$('rewardRows').querySelectorAll('[data-reward-row]')].map(row=>{const field=n=>row.querySelector('[data-reward-field="'+n+'"]');const n=v=>v===''?null:Number(v);return {...rewardDraft.rewards[Number(row.dataset.rewardRow)],name:field('name').value,group:field('group').value,qty:n(field('qty').value),chance:n(field('chance').value),guaranteed:field('guaranteed').checked,catalogId:field('catalogId').value,price:n(field('price').value)}})}
function rewardPreview(){collectRewardDraft();try{const e=evaluateRewards(rewardDraft,catalog);$('rewardPreview').textContent=(rewardDraft.valuationNote?rewardDraft.valuationNote+' · ':'')+'1개 평가 가치 (반올림): '+fmt(Math.round(e.price))+' 블다 · 확정 보상 '+fmt(e.guaranteed)+' + '+(e.mode==='choice'?'선택 보상 최고 가치 ':'랜덤 보상 기대값 ')+fmt(e.optional)+(e.assumptionHigh>e.price?' · 냥혼석 3,000 가정 시 '+fmt(e.assumptionHigh)+' 블다':'');$('rewardSave').disabled=false}catch(e){$('rewardPreview').textContent=e.message;$('rewardSave').disabled=true}}
function rewardUnitDisplay(r){try{return evaluateRewards({mode:'choice',rewards:[r]},catalog).price}catch{return r.price??''}}
function renderRewardRows(){
 $('rewardMode').value=rewardDraft.mode;
 $('rewardRows').innerHTML=rewardDraft.rewards.map((r,j)=>`<tr data-reward-row="${j}"><td><input data-reward-field="name" aria-label="보상 이름" value="${esc(r.name)}"></td><td><input data-reward-field="group" aria-label="추첨 묶음" value="${esc(r.group||'1')}"></td><td><input type="number" min="0" step="any" data-reward-field="qty" aria-label="획득 수량" value="${r.qty??''}"></td><td><input type="checkbox" data-reward-field="guaranteed" aria-label="확정 보상" ${r.guaranteed?'checked':''}></td><td><input type="number" min="0" max="100" step="any" data-reward-field="chance" aria-label="보상 확률 퍼센트" value="${r.chance??''}" ${r.guaranteed||rewardDraft.mode==='choice'?'disabled':''}></td><td><select data-reward-field="catalogId" aria-label="보상 시세 연결">${rewardOptions(r.catalogId)}</select>${r.priceEstimate?`<small>${esc(r.estimateNote||'추정가')}</small>`:''}</td><td><input type="number" min="0" step="any" data-reward-field="price" aria-label="보상 개당 블다" value="${rewardUnitDisplay(r)}" ${r.catalogId||r.priceEstimate||r.ticketPart||r.armorSummon?'disabled':''}></td><td><button data-remove-reward="${j}" aria-label="보상 행 삭제">×</button></td></tr>`).join('');rewardPreview();
}
function openRewardEditor(id){const item=s.items.find(i=>i.id===id);if(!item)return;rewardEditing=id;const faction=boxFactionFromName(item.name);if(faction)$('boxFaction').value=faction;rewardDraft=structuredClone(item.rewardRecipe||{mode:'random',rewards:[{name:'',qty:1,chance:100,guaranteed:false,price:null,catalogId:''}]});$('rewardTitle').textContent=item.name+' · 보상 가치';renderRewardRows();$('rewardDialog').showModal()}
