async function loadWorkspaces(){const r=await fetch('/api/guilds'),d=await apiJSON(r);if(!r.ok)throw Error(d.error);platformAdmin=!!d.admin;workspaceId=d.current||'none';workspaceRole=d.role||'none';workspaceChoices=d.guilds;$('gatewayConnect').hidden=!!d.adminPasswordSet||!!d.admin;$('gatewayConnectionNote').hidden=true;$('workspaceSelect').innerHTML=d.guilds.map(g=>`<option value="${esc(g.id)}">${esc(g.name)} · ${g.role==='owner'?'길드장':g.role==='editor'?'수정':g.role==='viewer'?'조회':'비밀번호 입장'}</option>`).join('');$('workspaceSelect').value=workspaceId;if(!$('workspaceSelect').value&&d.guilds.length)$('workspaceSelect').value=d.guilds[0].id;updatePasswordControls();$('workspaceStatus').textContent=workspaceRole==='none'?'길드를 선택하고 비밀번호를 입력하세요.':workspaceRole==='viewer'?'조회 전용 공간입니다.':'길드별 명단·활동·창고·시세·이월을 별도로 저장합니다.';$('workspaceAccess').innerHTML=(d.members||[]).map(m=>`<div class="access-row"><strong>${esc(m.nickname||(m.role==='owner'?'길드 관리자':'닉네임 미등록'))}</strong><span>${m.role==='pending'?'승인 대기':m.role==='owner'?'길드 관리자':m.role==='editor'?'수정 가능':'조회만'}</span>${m.role==='pending'?`<button data-access-action="approve" data-access-id="${esc(m.id)}" data-access-role="viewer">조회 승인</button><button data-access-action="approve" data-access-id="${esc(m.id)}" data-access-role="editor">수정 승인</button><button data-access-action="reject" data-access-id="${esc(m.id)}">거절</button>`:m.role!=='owner'?`<button data-access-action="setRole" data-access-id="${esc(m.id)}" data-access-role="${m.role==='editor'?'viewer':'editor'}">${m.role==='editor'?'조회로 변경':'수정 권한 부여'}</button>`:''}</div>`).join('');if(d.admin)$('workspaceStatus').textContent='서비스 관리자 · 모든 길드 공간을 조회·관리할 수 있습니다.';$('workspaceInvite').hidden=workspaceRole!=='owner'&&!platformAdmin;$('adminSetupNote').hidden=!d.admin||d.adminPasswordSet;$('localLogout').hidden=workspaceRole==='none';$('credentialRole').querySelector('option[value=admin]').hidden=!platformAdmin;applyWorkspacePermissions();scheduleTableLayout();}
function applyWorkspacePermissions(){document.querySelectorAll('[data-subscope="prices"][data-subkey="register"],[data-subpanel="prices"][data-subkey="register"]').forEach(el=>{if(!platformAdmin)el.hidden=true;else if(el.tagName==='BUTTON')el.hidden=false});document.querySelectorAll('[data-permission-disabled]').forEach(el=>{el.disabled=false;delete el.dataset.permissionDisabled});if(platformAdmin||workspaceRole!=='viewer'&&workspaceRole!=='none')return;document.querySelectorAll('main input,main select,main textarea,main button,#floatingTableContent input,#floatingTableContent select,#floatingTableContent textarea,#floatingTableContent button').forEach(el=>{const allowed=el.dataset.tableControl!==undefined||el.closest('.table-pager')||el.dataset.faqDetail!==undefined||el.dataset.questionDetail!==undefined||el.dataset.floating!==undefined||el.id==='backup'||el.id==='csv'||el.id.startsWith('filter-')||el.id==='showSettled'||el.id==='payoutSelection'||el.id==='battleRun'||el.dataset.tab||el.dataset.subscope||el.dataset.marketTab!==undefined||el.id.startsWith('suggestion')||el.dataset.suggestionDetail!==undefined||el.id.startsWith('priceRequest')||el.dataset.requestPrice!==undefined||el.id.startsWith('support')||el.id.startsWith('faq')||el.id.startsWith('workspace')||el.id.startsWith('gateway')||el.id==='priceAdminLogin'||platformAdmin&&el.id.startsWith('credential');if(!allowed&&!el.disabled){el.disabled=true;el.dataset.permissionDisabled='true'}});}
