let layoutQueued=false;const tablePages=new WeakMap(),tableHeights=new WeakMap();const rowChoices={};try{Object.assign(rowChoices,JSON.parse(localStorage.getItem('table-row-choices')||'{}'))}catch{}
function rowScope(table){if(table.closest('#members')||table.tBodies[0]?.id==='members')return 'members';if(['contentTrophyRows','battleScores'].includes(table.tBodies[0]?.id))return 'content';if(table.parentElement.id==='results'||table.closest('#history'))return 'payout';if(table.closest('#panel-prices'))return 'prices';return ''}
function rowChoice(scope){const options=scope==='prices'?['auto','10','20','30','50','all']:['auto','5','10','15','20'];return options.includes(rowChoices[scope])?rowChoices[scope]:'20';}
function scheduleTableLayout(){if(layoutQueued)return;layoutQueued=true;requestAnimationFrame(()=>{layoutQueued=false;fitDropdowns();layoutTables()})}
function layoutTables(){if($('dashboard').hidden)return;document.querySelectorAll('#dashboard .scroll > table').forEach(table=>{if(!table.getClientRects().length)return;const tbody=table.tBodies[0];if(!tbody)return;const rows=[...tbody.rows];if(!rows.length)return;let pager=table.previousElementSibling;if(!pager?.classList.contains('table-pager')){pager=document.createElement('div');pager.className='table-pager';const prev=document.createElement('button'),label=document.createElement('span'),next=document.createElement('button');label.className='page-label';prev.type=next.type='button';prev.textContent='이전';next.textContent='다음';prev.setAttribute('aria-label','이전 페이지');next.setAttribute('aria-label','다음 페이지');const expand=document.createElement('button');expand.type='button';expand.textContent='크게 보기 ↗';expand.dataset.floating='true';expand.onclick=()=>openFloatingTable(table.parentElement);pager.append(prev,label,next,expand);const scope=rowScope(table);if(scope){const wrap=document.createElement('label');wrap.className='row-count';wrap.textContent='표시 개수 ';const select=document.createElement('select');select.dataset.tableControl='true';select.setAttribute('aria-label','한 번에 표시할 개수');select.innerHTML='<option value="auto">화면에 맞춤</option>'+(scope==='prices'?[10,20,30,50]:[5,10,15,20]).map(n=>`<option value="${n}">${n}${scope==='prices'?'개':'명'}</option>`).join('')+(scope==='prices'?'<option value="all">전체</option>':'');select.value=rowChoice(scope);select.onchange=()=>{rowChoices[scope]=select.value;try{localStorage.setItem('table-row-choices',JSON.stringify(rowChoices))}catch{}tablePages.set(table,0);table.parentElement.scrollTop=0;scheduleTableLayout()};wrap.append(select);pager.prepend(wrap);}table.before(pager);prev.onclick=()=>{tablePages.set(table,Math.max(0,(tablePages.get(table)||0)-1));scheduleTableLayout()};next.onclick=()=>{tablePages.set(table,(tablePages.get(table)||0)+1);scheduleTableLayout()};}
const scroll=table.parentElement,scope=rowScope(table),choice=rowChoice(scope);scroll.classList.add('configurable-table');
if(!scope||choice==='auto')scroll.scrollTop=0;
const footer=$('systemControls').getBoundingClientRect(),dashboard=$('dashboard').getBoundingClientRect();
let reserved=12;let sibling=scroll.nextElementSibling;while(sibling){if(sibling.getClientRects().length)reserved+=sibling.getBoundingClientRect().height+8;sibling=sibling.nextElementSibling;}
const bottom=Math.min(dashboard.bottom-8,footer.top>scroll.getBoundingClientRect().top?footer.top-8:dashboard.bottom-8);
const available=Math.max(100,bottom-scroll.getBoundingClientRect().top-reserved);
scroll.style.height=available+'px';scroll.style.maxHeight=available+'px';
const pagerHeight=pager.getBoundingClientRect().height;scroll.style.setProperty('--pager-height',pagerHeight+'px');
const header=table.tHead?.getBoundingClientRect().height||40;
const maxRow=Math.max(1,...rows.filter(r=>!r.hidden).map(r=>r.getBoundingClientRect().height));
const measured=maxRow>1?maxRow:(tableHeights.get(table)||40);tableHeights.set(table,measured);
const fit=Math.max(1,Math.floor((scroll.clientHeight-pagerHeight-header-4)/measured));
const pageSize=scope?(choice==='all'?rows.length:choice==='auto'?fit:Number(choice)||20):fit;
const pages=Math.max(1,Math.ceil(rows.length/pageSize)),page=Math.min(tablePages.get(table)||0,pages-1);tablePages.set(table,page);rows.forEach((row,i)=>row.hidden=i<page*pageSize||i>=(page+1)*pageSize);pager.hidden=false;pager.querySelectorAll('button')[0].hidden=pages<=1;pager.querySelectorAll('button')[1].hidden=pages<=1;pager.querySelectorAll('button')[0].disabled=page===0;pager.querySelectorAll('button')[1].disabled=page>=pages-1;const label=`${page+1} / ${pages} · 총 ${rows.length}건`;if(pager.querySelector('.page-label').textContent!==label)pager.querySelector('.page-label').textContent=label;
});}
new MutationObserver(scheduleTableLayout).observe($('dashboard'),{childList:true,subtree:true});window.addEventListener('resize',()=>{document.querySelectorAll('#dashboard .scroll > table').forEach(t=>tableHeights.delete(t));scheduleTableLayout()});document.addEventListener('click',scheduleTableLayout);document.addEventListener('change',scheduleTableLayout);scheduleTableLayout();
