function renderContentTrophies(){$('contentPeriods').innerHTML=contentBases.map(b=>`<label>${basisName[b]} 회차<input type="date" data-content-period="${b}" value="${esc(s.contentPeriods?.[b]||s.period)}"></label>`).join('');$('contentTrophyRows').innerHTML=s.members.map(m=>`<tr><td>${esc(m.name)}</td>${contentBases.map(b=>`<td><input type="number" min="0" step="1" aria-label="${esc(m.name)} ${basisName[b]} 트로피" data-content-member="${m.id}" data-content-basis="${b}" value="${m.contentTrophies?.[b]??0}"></td>`).join('')}</tr>`).join('');}
document.addEventListener('change',e=>{const b=e.target.dataset.contentBasis;if(b){const m=s.members.find(m=>m.id===e.target.dataset.contentMember);m.contentTrophies={...m.contentTrophies,[b]:Number(e.target.value)};update()}if(e.target.dataset.contentPeriod){s.contentPeriods={...s.contentPeriods,[e.target.dataset.contentPeriod]:e.target.value};update()}});
const faqEntries=[['격전지 보상은 어떤 기준으로 분배하나요?','일반 격전지 일반 보상은 참여자 균등, 빨강·파랑·보라 상자는 출처 몬스터 점수 또는 보상 기여율로 배분합니다. 은하·균열 외형 소환권은 각각 해당 트로피로 배분합니다. 길드 트로피는 기록용이며 분배에서 제외합니다. 레이스와 점령전 보상은 기존 별도 포인트를 유지합니다.'],["길드 경험치와 레벨은 어떻게 관리하나요?", "등록한 레벨별 기준을 넘으면 레벨과 남은 경험치를 자동 계산합니다. 게임 계정에서 경험치를 직접 가져오는 연결은 없으며, 활동 분배 포인트는 길드 경험치로 환산하지 않습니다.\n\n공개 자료에서 검증된 전체 경험치 표를 확인하지 못했습니다 (2026-10-08 조사). 게임에 표시된 현재 레벨 → 다음 레벨 필요 경험치를 등록하세요. 기준이 없는 레벨에서는 자동 승급을 멈추고 남은 경험치를 유지합니다.\n\n조사 자료: 게임듀오 · 공식 앱 업데이트 · 캣히어로 허브. 최대 레벨·레벨별 필요 EXP·활동별 길드 EXP 환산율은 확인되지 않았습니다."], ["길드원 트로피와 기준 기여도는 어떻게 입력하나요?", "주간 트로피는 직접 입력 또는 현재 − 기준 기여도로 계산합니다.\n\n한 줄에 닉네임과 트로피를 탭 또는 쉼표로 구분하세요. 기존 인원은 유지됩니다."], ["점령·방어와 레이스 포인트는 어떻게 기록하나요?", "현재 정산 회차에 기록합니다. 점령·방어는 합산, 레이스는 별도 집계합니다. 점령·방어는 횟수 × 회당 점수, 레이스는 미션에 표시된 포인트를 직접 입력합니다. 기존 기록의 점수는 유지됩니다."], ["예전 격전지 기록은 어떻게 되나요?", "기존 격전지 트로피와 정산 기록은 보존됩니다. 새 격전지 몬스터 점수와 은하·균열 트로피를 별도로 입력합니다."], ["창고 아이템 등록·정산 후 보관은 어떻게 되나요?", "시세 DB에서 아이템을 선택하면 최신 단가가 자동 반영됩니다. 장비는 옵션·거래 가능 횟수별로 구분해 등록하세요.\n\n정산 완료 아이템은 기본 목록에서 숨깁니다. 기록·시세 연결·이월은 보관하며, 수량을 다시 입력하면 목록에 나타납니다.\n\n비거래 재화와 상자는 종류마다 트로피·점령/방어·레이스·전체 균등 중 기준을 선택합니다. 블다 가치 분배는 선택한 출처 기준을 따르며 상자·교환권의 기대값도 지급 가치에 포함됩니다. 예시 가격은 현재 시세가 아닙니다."],['지급표를 어떻게 확정하나요?','게임에서 지급표에 표시된 수량을 실제로 지급한 뒤 지급 완료 · 회차 확정을 누르세요. 사이트는 게임 내 지급을 실행하지 않습니다.'],['정수 배분 차이와 이월은 어떻게 계산하나요?','정수 단위의 지급 차이는 다음 회차로 이월됩니다. 시장가 아이템은 큰 단가부터 남은 권리가 가장 큰 사람에게 배정합니다. 동률은 명단 순서이며 이월 잔액으로 다음 회차를 보정합니다.'],['어떤 트로피로 보상을 나누나요?','일반 보상은 격전지 참여자 균등, 상자는 몬스터 점수·딜 기여율로 나눕니다. 은하·균열 외형 소환권은 해당 콘텐츠 트로피로 계산하며 기존 길드 트로피는 기록용입니다. 레이스와 점령전은 각각 활동 포인트를 사용합니다.'],['일부 보상만 지급하려면?','지급표의 지급할 항목에서 출처 전체 또는 개별 아이템을 선택하세요. 선택한 항목만 계산·CSV·지급 확정에 포함됩니다. 격전지 보상은 출처 몬스터를 연결하며 레이스·점령전은 각각의 활동 회차로 관리합니다.'],['지급하면 트로피가 초기화되나요?','기록용 길드 트로피는 지급해도 초기화하지 않습니다. 은하·균열 트로피는 해당 출처 보상을 모두 정산한 뒤 초기화됩니다. 레이스·점령전 포인트는 해당 보상을 모두 정산할 때 별도로 초기화되며 확정 당시 값은 기록에 남습니다.'],['총 기여도와 주간 트로피는 어떻게 기록하나요?','총 기여도와 주간 트로피는 각각 직접 입력합니다. 서로 자동 계산하거나 변경하지 않으며, 길드 트로피는 기록용으로 보관합니다.'],['활동 포인트를 잘못 입력했어요.','활동 포인트 → 활동 기록에서 잘못된 기록을 취소하고 올바른 값으로 다시 등록하세요. 취소 이력은 남습니다.'],['아이템 시세는 어떻게 연결하나요?','시세 DB에서 조사한 최저가를 등록하고 창고에서 시세 DB 연동과 해당 아이템을 선택하세요. 상자는 보상·확률 설정으로 기대값을 계산합니다.'],['데이터는 어디에 저장되나요?','Cloudflare D1에 저장되고 구글시트는 조회용으로 동기화됩니다. GitHub DB 백업은 관리자가 별도로 연결해 실행합니다.'],['문의는 누가 답변하나요?','페이지 관리자 민초캣이 답변합니다. 질문을 아직 확인하지 않았거나 답변이 늦어지면 인게임에서 민초캣에게 귓말로 문의하셔도 응대 가능합니다.']];
let faqPage=0,supportPage=0,supportQuestions=[],supportCanAnswer=false;
function openSupportDetail(title,body){$('supportDetailTitle').textContent=title;$('supportDetailBody').innerHTML=body;$('supportDetail').showModal();}
$('supportDetailClose').onclick=()=>$('supportDetail').close();
faqEntries.push(['변경 이력과 자동 백업은 어디에서 확인하나요?','길드·길드원·활동의 변경·복원 탭에서 확인합니다. 최근 변경 이력 300개와 변경 직전 백업 30개를 길드별로 보관합니다. 복원은 명단·창고·정산·활동 상태에 적용되며 고정 시세와 비밀번호는 유지됩니다. 이후 활동은 취소 상태로 남습니다. 공용 비밀번호이므로 작성자를 확정할 수 없습니다.'],['내 지급 내역과 디스코드 공지는 어디에 있나요?','지급표의 내 지급 내역에서 닉네임을 선택하세요. 정산 기록의 최근 정산 공지 복사 버튼은 마지막 확정 결과와 연결된 시트 링크를 복사합니다. 디스코드 전송은 직접 붙여넣어 진행합니다.']);
function renderFAQ(){const q=$('faqSearch').value.trim().toLowerCase(),entries=faqEntries.map((e,index)=>({e,index})).filter(({e})=>e.join(' ').toLowerCase().includes(q));faqPage=Math.min(faqPage,Math.max(0,Math.ceil(entries.length/12)-1));$('faqList').innerHTML=entries.slice(faqPage*12,faqPage*12+12).map(({e,index})=>`<button class="support-row" data-faq-detail="${index}">${esc(e[0])}</button>`).join('')||'<p>관련 FAQ가 없습니다. 질문 등록을 이용하세요.</p>';$('faqPrevious').disabled=faqPage===0;$('faqNext').disabled=(faqPage+1)*12>=entries.length;$('faqPage').textContent=(faqPage+1)+' / '+Math.max(1,Math.ceil(entries.length/12));}
$('faqSearch').oninput=()=>{faqPage=0;renderFAQ()};$('faqPrevious').onclick=()=>{faqPage--;renderFAQ()};$('faqNext').onclick=()=>{faqPage++;renderFAQ()};renderFAQ();
async function loadQuestions(){try{const r=await fetch('/api/questions?page='+supportPage),d=await apiJSON(r);if(!r.ok)throw Error(d.error);supportQuestions=d.questions;supportCanAnswer=d.canAnswer;$('supportQuestions').innerHTML=d.questions.map(q=>`<button class="support-row" data-question-detail="${esc(q.id)}"><span>${esc(q.title)}</span><small>${q.private?'비공개 · ':''}${q.status==='answered'?'답변 완료':'답변 대기'} · ${esc(q.nickname)}</small></button>`).join('')||'<p>등록된 질문이 없습니다.</p>';$('supportPrevious').disabled=supportPage===0;$('supportNext').disabled=!d.hasMore;$('supportPage').textContent=(supportPage+1)+' 페이지';}catch(e){$('supportQuestions').textContent=e.message}}
document.addEventListener('click',e=>{const f=e.target.closest('[data-faq-detail]');if(f){const [q,a]=faqEntries[Number(f.dataset.faqDetail)];openSupportDetail(q,`<p class="question-text">${esc(a)}</p>`)}const el=e.target.closest('[data-question-detail]');if(el){const q=supportQuestions.find(q=>q.id===el.dataset.questionDetail);if(!q)return;openSupportDetail(q.title,`<p class="note">${q.private?'비공개 · ':''}${esc(q.nickname)} · ${q.status==='answered'?'답변 완료':'답변 대기'}</p><p class="question-text">${esc(q.body)}</p>${q.answer?`<p class="question-answer">${esc(q.answer)}</p>`:''}${supportCanAnswer?`<form data-question-answer="${esc(q.id)}"><textarea aria-label="관리자 답변" maxlength="4000" rows="4" required>${esc(q.answer)}</textarea><button type="submit">답변 저장</button></form>`:''}`)}});
$('supportForm').onsubmit=async e=>{e.preventDefault();$('supportSubmit').disabled=true;try{const r=await fetch('/api/questions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nickname:$('supportNickname').value,title:$('supportTitle').value,body:$('supportBody').value,private:$('supportPrivate').checked})}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);$('supportForm').reset();$('supportStatus').textContent='질문을 등록했습니다.';supportPage=0;await loadQuestions();showSub('support','questions')}catch(e){$('supportStatus').textContent=e.message}finally{$('supportSubmit').disabled=false}};
$('supportReload').onclick=loadQuestions;$('supportPrevious').onclick=()=>{supportPage=Math.max(0,supportPage-1);loadQuestions()};$('supportNext').onclick=()=>{supportPage++;loadQuestions()};
document.addEventListener('click',e=>{if(e.target.dataset.tab==='support'||e.target.dataset.subscope==='support'&&e.target.dataset.subkey==='questions')loadQuestions()});
document.addEventListener('submit',async e=>{const id=e.target.dataset.questionAnswer;if(!id)return;e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const r=await fetch('/api/questions',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,answer:e.target.querySelector('textarea').value})}),d=await apiJSON(r);if(!r.ok)throw Error(d.error||'답변 저장 실패');await loadQuestions();$('supportDetail').close()}catch(e){alert(e.message)}finally{button.disabled=false}});

let floatingSource=null,floatingMarker=null,floatingTrigger=null;
function openFloatingTable(source){if($('floatingTable').open)return;floatingSource=source;floatingTrigger=document.activeElement;floatingMarker=document.createComment('floating-table-position');source.before(floatingMarker);const section=source.closest('section');$('floatingTableTitle').textContent=section?.querySelector('h2,h3')?.textContent||source.closest('[data-panel]')?.getAttribute('data-panel')||'표 크게 보기';$('floatingTableContent').append(source);source.querySelectorAll('tbody tr').forEach(row=>row.hidden=false);$('floatingTable').showModal();fitDropdowns();applyWorkspacePermissions();}
$('floatingTableClose').onclick=()=>$('floatingTable').close();
$('floatingTable').addEventListener('close',()=>{if(floatingSource&&floatingMarker?.parentNode){floatingMarker.replaceWith(floatingSource);floatingSource.querySelectorAll('table').forEach(t=>tableHeights.delete(t));}floatingSource=floatingMarker=null;scheduleTableLayout();floatingTrigger?.focus();});
new MutationObserver(()=>{if($('floatingTable').open){$('floatingTableContent').querySelectorAll('tbody tr').forEach(row=>row.hidden=false);applyWorkspacePermissions();}}).observe($('floatingTableContent'),{childList:true,subtree:true});

function renderDistributionControls(){
 $('payoutMinimum').innerHTML=selectedItems(s).filter(i=>i.qty>0).map(i=>`<label data-item="${esc(i.id)}"><input type="checkbox" data-field="minimumPerParticipant" ${minimumEach(i)?'checked':''}> ${esc(i.name)} · 참여자 최소 1개</label>`).join('');
 const target=$('rewardItemTarget'),value=target.value;target.innerHTML=s.items.map(i=>`<option value="${esc(i.id)}">${esc(i.name)}</option>`).join('');if(s.items.some(i=>i.id===value))target.value=value;
 $('dbRewardEdit').disabled=$('dbAttributeEdit').disabled=!s.items.length;
}
$('dbRewardEdit').onclick=()=>{if($('rewardItemTarget').value)openRewardEditor($('rewardItemTarget').value)};
$('dbAttributeEdit').onclick=()=>{const id=$('rewardItemTarget').value;if(id){const button=document.createElement('button');button.dataset.editWarehouse=id;document.body.append(button);button.click();button.remove()}};

function fitDropdowns(){const header=document.querySelector('header');if(header)document.documentElement.style.setProperty('--app-header-height',Math.ceil(header.getBoundingClientRect().height)+'px');const bar=document.querySelector('.system-controls');if(bar&&!$('dashboard').hidden)document.documentElement.style.setProperty('--db-bar-height',Math.ceil(bar.getBoundingClientRect().height)+'px');
 document.querySelectorAll('select').forEach(select=>{if(!select.getClientRects().length)return;let shell=select.parentElement;if(!shell.classList.contains('select-shell')){shell=document.createElement('span');shell.className='select-shell';const value=document.createElement('span');value.className='select-value';value.setAttribute('aria-hidden','true');select.before(shell);shell.append(value,select);}const text=select.selectedOptions[0]?.textContent||'선택';const value=shell.querySelector('.select-value');if(value.textContent!==text)value.textContent=text;shell.classList.toggle('is-disabled',select.disabled);select.title=text;});
 document.querySelectorAll('.scroll > table').forEach(table=>{const headers=[...(table.tHead?.rows[0]?.cells||[])];const columns=headers.length;table.classList.toggle('stacked-table',columns>5&&table.parentElement.clientWidth<columns*115);table.querySelectorAll('tbody tr').forEach(row=>[...row.cells].forEach((cell,index)=>{cell.dataset.label=headers[index]?.textContent.trim()||'작업'}));});
}

$('priceRequestForm').onsubmit=async e=>{e.preventDefault();$('priceRequestSubmit').disabled=true;try{const r=await fetch('/api/price-requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({itemId:$('priceRequestItem').value,nickname:$('priceRequestNickname').value,price:Number($('priceRequestValue').value),reason:$('priceRequestReason').value})}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);$('priceRequestStatus').textContent='요청이 등록되었습니다. 민초캣 확인 후 반영됩니다.';if(platformAdmin)loadPriceRequests()}catch(e){$('priceRequestStatus').textContent=e.message}finally{$('priceRequestSubmit').disabled=false}};
document.addEventListener('click',e=>{if(e.target.dataset.requestPrice){$('priceRequestItem').value=e.target.dataset.requestPrice;activateTab('prices');showSub('prices','request')}});
async function loadPriceRequests(){if(!platformAdmin)return;try{const r=await fetch('/api/price-requests'),d=await apiJSON(r);if(!r.ok)throw Error(d.error);$('priceRequestsList').innerHTML=d.requests.length?d.requests.map(q=>`<article class="question-card"><strong>${esc(q.guild_name)} · ${esc(q.item_name)}</strong><p>${esc(q.nickname)} · ${esc(shortObserved(q.created_at))} · ${esc(q.status==='pending'?'대기':q.status==='approved'?'승인':'반려')}</p><p>${fmt(Number(q.old_price))} → ${fmt(q.proposed_price)} 블다</p><p>${esc(q.reason)}</p>${q.status==='pending'?`<button data-price-request-id="${esc(q.id)}" data-price-request-action="approve">승인·시세 반영</button> <button data-price-request-id="${esc(q.id)}" data-price-request-action="reject">반려</button>`:''}</article>`).join(''):'등록된 요청이 없습니다.';$('priceRequestsStatus').textContent='최근 100건 · 대기 요청 우선'}catch(e){$('priceRequestsStatus').textContent=e.message}}
$('priceRequestsReload').onclick=loadPriceRequests;
document.addEventListener('click',async e=>{const id=e.target.dataset.priceRequestId;if(!id||!platformAdmin)return;const action=e.target.dataset.priceRequestAction;if(!confirm(action==='approve'?'요청 가격을 해당 길드의 시세 DB에 반영할까요?':'요청을 반려할까요?'))return;e.target.disabled=true;try{const r=await fetch('/api/price-requests',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,action})}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);await loadPriceRequests();await loadPrices()}catch(e){$('priceRequestsStatus').textContent=e.message}finally{e.target.disabled=false}});

const suggestionLabels={new:'접수',reviewing:'검토 중',planned:'반영 예정',done:'반영 완료',deferred:'보류'};
let suggestionPage=0,suggestionAdminPage=0,suggestionRows=[],suggestionAdminRows=[];
async function loadSuggestions(admin=false){if(admin&&!platformAdmin)return;const prefix=admin?'suggestionAdmin':'suggestion';try{const r=await fetch('/api/suggestions?page='+(admin?suggestionAdminPage:suggestionPage)),d=await apiJSON(r);if(!r.ok)throw Error(d.error);if(admin)suggestionAdminRows=d.suggestions;else suggestionRows=d.suggestions;$(prefix+'List').innerHTML=d.suggestions.length?d.suggestions.map(q=>`<article class="question-card"><button data-suggestion-detail="${esc(q.id)}" data-suggestion-admin="${admin?'1':'0'}">${esc(q.title)}</button><p>${esc(q.type)} · ${esc(suggestionLabels[q.status]||q.status)} · ${esc(q.nickname)}${admin?' · '+esc(q.guild_name):''}${q.private?' · 비공개':''} · ${esc(shortObserved(q.created_at))}</p></article>`).join(''):'등록된 개선 제안이 없습니다.';$(prefix+'Page').textContent=(d.page+1)+' 페이지';$(prefix+'Previous').disabled=d.page===0;$(prefix+'Next').disabled=!d.hasMore;if(admin)$(prefix+'Message').textContent='전체 길드 · 접수된 제안 우선';fitDropdowns();}catch(e){$(prefix+'Message').textContent=e.message}}
$('suggestionForm').onsubmit=async e=>{e.preventDefault();$('suggestionSubmit').disabled=true;try{const r=await fetch('/api/suggestions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:$('suggestionType').value,nickname:$('suggestionNickname').value,title:$('suggestionTitle').value,body:$('suggestionBody').value,private:$('suggestionPrivate').checked})}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);$('suggestionForm').reset();$('suggestionMessage').textContent='제안이 접수되었습니다. 목록에서 검토 상태와 답변을 확인하세요.';suggestionPage=0;await loadSuggestions()}catch(e){$('suggestionMessage').textContent=e.message}finally{$('suggestionSubmit').disabled=false}};
for(const admin of [false,true]){const prefix=admin?'suggestionAdmin':'suggestion';$(prefix+'Reload').onclick=()=>loadSuggestions(admin);$(prefix+'Previous').onclick=()=>{if(admin)suggestionAdminPage=Math.max(0,suggestionAdminPage-1);else suggestionPage=Math.max(0,suggestionPage-1);loadSuggestions(admin)};$(prefix+'Next').onclick=()=>{if(admin)suggestionAdminPage++;else suggestionPage++;loadSuggestions(admin)}}
document.addEventListener('click',e=>{if(e.target.dataset.subscope==='support'&&e.target.dataset.subkey==='suggest')loadSuggestions();if(e.target.dataset.subscope==='admin'&&e.target.dataset.subkey==='suggest')loadSuggestions(true);const el=e.target.closest('[data-suggestion-detail]');if(!el)return;const admin=el.dataset.suggestionAdmin==='1',q=(admin?suggestionAdminRows:suggestionRows).find(q=>q.id===el.dataset.suggestionDetail);if(!q)return;openSupportDetail(q.title,`<p class="note">${esc(q.nickname)} · ${esc(q.type)} · ${esc(suggestionLabels[q.status])}${q.private?' · 비공개':''}</p><p class="question-text">${esc(q.body)}</p>${q.answer?`<p class="question-answer">민초캣: ${esc(q.answer)}</p>`:''}${admin&&platformAdmin?`<form data-suggestion-manage="${esc(q.id)}"><label>검토 상태<select name="status">${Object.entries(suggestionLabels).map(([k,v])=>`<option value="${k}" ${q.status===k?'selected':''}>${v}</option>`).join('')}</select></label><label>관리자 답변<textarea name="answer" maxlength="4000" rows="4">${esc(q.answer)}</textarea></label><button type="submit">검토 내용 저장</button></form>`:''}`);fitDropdowns()});
document.addEventListener('submit',async e=>{const id=e.target.dataset.suggestionManage;if(!id)return;e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{const r=await fetch('/api/suggestions',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,status:form.elements.status.value,answer:form.elements.answer.value})}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);await loadSuggestions(true);$('supportDetail').close()}catch(e){alert(e.message)}finally{button.disabled=false}});

$('sheetAutoRequest').onclick=async()=>{const b=$('sheetAutoRequest');b.disabled=true;try{const r=await fetch('/api/sheet-request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({publicLink:$('sheetPublicLink').checked})}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);$('sheetConnectStatus').textContent=d.connected?'시트 생성·연결 완료. 공유 시트 열기에서 확인하세요.':d.error||'신청이 저장되었습니다. 관리자의 Google 생성 권한 설정 후 처리됩니다.';await checkSheet()}catch(e){$('sheetConnectStatus').textContent=e.message}finally{b.disabled=false}};
async function loadSheetRequests(){if(!platformAdmin)return;try{const r=await fetch('/api/sheet-request'),d=await apiJSON(r);if(!r.ok)throw Error(d.error);$('sheetProvisionStatus').textContent=d.configured?'자동 생성 설정 등록됨 · 실제 Google 권한은 생성 시 확인합니다.':'자동 생성 대기 · 관리자 Google 생성 권한 설정이 필요합니다.';$('sheetRequestsList').innerHTML=d.requests.map(q=>`<div class="access-row"><strong>${esc(q.name)}</strong><span>${esc(({pending:'접수',creating:'생성 중',done:'연결 완료',error:'재시도 필요'})[q.status]||q.status)} · ${q.public_link?'링크 조회 허용':'비공개'}</span>${q.status!=='done'?`<button data-sheet-provision="${esc(q.guild_id)}">생성 재시도</button>`:''}</div>`).join('')||'<p>신청이 없습니다.</p>'}catch(e){$('sheetProvisionStatus').textContent=e.message}}
$('sheetRequestsReload').onclick=loadSheetRequests;
document.addEventListener('click',async e=>{if(e.target.dataset.subscope==='admin'&&e.target.dataset.subkey==='sheets')loadSheetRequests();const id=e.target.dataset.sheetProvision;if(!id)return;e.target.disabled=true;try{const r=await fetch('/api/sheet-request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({guildId:id})}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);if(d.error)alert(d.error);else if(d.pending)alert('신청이 대기 중입니다. Google 생성 권한 설정을 확인하세요.');await loadSheetRequests()}catch(e){alert(e.message)}finally{e.target.disabled=false}});

async function localAction(payload){const r=await fetch('/api/local-auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);return d}
$('credentialSave').onclick=async()=>{try{await localAction({action:'password',guildId:workspaceId,role:$('credentialRole').value,password:$('credentialPassword').value});$('credentialPassword').value='';$('credentialStatus').textContent='저장 완료. 해당 비밀번호의 기존 세션은 만료됩니다.';await loadWorkspaces()}catch(e){$('credentialStatus').textContent=e.message}};
$('localLogout').onclick=async()=>{if(pending||saving){alert('DB 저장 완료 후 로그아웃하세요.');return}await localAction({action:'logout'});location.reload()};

if($('signIn'))$('signIn').onclick=e=>{e.preventDefault();showGateway()};

let settlementFingerprint='',auditPage=0,auditHasMore=false;
$('settlementClose').onclick=()=>$('settlementReview').close();
$('settlementAcknowledged').onchange=e=>$('settlementCommit').disabled=!e.target.checked;
$('settlementCommit').onclick=async()=>{const b=$('settlementCommit');b.disabled=true;try{if(!$('settlementAcknowledged').checked)throw Error('실제 지급 완료를 확인하세요.');if(!await loadPrices()||!await refreshActivityForSettlement())throw Error('최신 데이터를 확인하지 못했습니다.');if(settlementFingerprint!==JSON.stringify({state:s,plan}))throw Error('내용이 변경됐습니다. 확인창을 닫고 다시 확인하세요.');const r=await fetch('/api/state'),d=await apiJSON(r);if(!r.ok||d.revision!==revision)throw Error('다른 창에서 데이터가 변경됐습니다. DB를 다시 불러오세요.');s=settleSelected(s,plan,activityRecords);renderInputs();clearTimeout(saveTimer);await pushState();if(pending||conflict)throw Error('정산 결과가 아직 DB에 저장되지 않았습니다. DB 저장 재시도를 누르세요.');$('settlementReview').close();renderPersonal();}catch(e){$('settlementStatus').textContent=e.message}finally{b.disabled=true}};
function renderPersonal(){const selected=$('personalMember').value,people=new Map(s.members.map(m=>[m.id,m.name]));for(const h of s.history)for(const r of h.plan?.rows||[])people.set(r.member.id,r.member.name);$('personalMember').innerHTML=[...people].map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('');if(people.has(selected))$('personalMember').value=selected;const rows=receiptRows(s.history,$('personalMember').value).reverse();$('personalReceipts').innerHTML=rows.length?rows.map(r=>`<article class="question-card"><strong>${esc(r.period)}</strong><p>${r.items.map(i=>esc(i.name)+' '+fmt(i.qty)+'개').join(' · ')||'지급 아이템 없음'}</p><p>지급 가치 ${fmt(r.paid)} 블다 · 당시 다음 이월 ${fmt(r.carry)} 블다</p></article>`).join(''):'확정한 지급 내역이 없습니다.';}
$('personalMember').onchange=renderPersonal;
$('noticeCopy').onclick=async()=>{if(pending||saving){alert('DB 저장 완료 후 공지를 작성하세요.');return}const h=s.history.at(-1);if(!h){alert('확정한 정산이 없습니다.');return}const text=settlementNotice(h,sheetConnection?.sheetUrl||'');$('noticeText').value=text;$('noticeDialog').showModal();try{await navigator.clipboard.writeText(text);$('noticeStatus').textContent='복사했습니다. 디스코드에 붙여넣으세요.'}catch{$('noticeText').select();$('noticeStatus').textContent='위 내용을 선택해 복사하세요.'}};
$('noticeClose').onclick=()=>$('noticeDialog').close();
async function loadRecovery(){try{const r=await fetch('/api/recovery?page='+auditPage),d=await apiJSON(r);if(!r.ok)throw Error(d.error);auditHasMore=d.hasMore;$('auditPrev').disabled=auditPage===0;$('auditNext').disabled=!d.hasMore;$('auditPage').textContent=(auditPage+1)+'페이지';$('recoverySnapshot').innerHTML=d.snapshots.map(x=>`<option value="${x.id}">${esc(new Date(x.created_at).toLocaleString('ko-KR'))} · 버전 ${x.revision}</option>`).join('');$('auditList').innerHTML=d.audit.map(a=>{const detail=JSON.parse(a.detail_json);let lines=a.entity==='state'?stateChangeSummary(detail):a.entity==='activity'?[`${detail.nickname} · ${activityName[detail.activity]||detail.activity} ${detail.points}점 · ${detail.voided?'취소':'유효'} · ${detail.note||''}`]:['백업 #'+detail.snapshotId+' 복원'];return `<details><summary>${esc(new Date(a.created_at).toLocaleString('ko-KR'))} · ${a.entity==='state'?'길드 데이터':a.entity==='activity'?'활동':'복원'} 변경</summary><p>작성자 미확인 · 공용 비밀번호</p>${lines.slice(0,100).map(x=>`<p>${esc(x)}</p>`).join('')||'<p>초기 저장 또는 데이터 갱신</p>'}</details>`}).join('')||'변경 이력이 없습니다.';$('recoveryStatus').textContent='최근 백업 30개 · 변경 이력 300개 · 현재 길드만 표시'}catch(e){$('recoveryStatus').textContent=e.message}}
$('recoveryReload').onclick=loadRecovery;$('auditPrev').onclick=()=>{auditPage=Math.max(0,auditPage-1);loadRecovery()};$('auditNext').onclick=()=>{if(auditHasMore){auditPage++;loadRecovery()}};
$('recoveryRestore').onclick=async()=>{if(pending||saving||conflict){alert('현재 DB 저장을 완료한 뒤 복원하세요.');return}const id=Number($('recoverySnapshot').value);if(!id||!confirm('선택한 시점의 명단·창고·정산·활동 상태로 복원합니다. 이후 활동은 취소 상태로 남고, 현재 상태도 자동 백업됩니다. 진행할까요?'))return;const b=$('recoveryRestore');b.disabled=true;try{const r=await fetch('/api/recovery',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,revision})}),d=await apiJSON(r);if(!r.ok)throw Error(d.error);await loadState();await loadRecovery();renderPersonal()}catch(e){$('recoveryStatus').textContent=e.message}finally{b.disabled=false}};
document.addEventListener('click',e=>{if(e.target.dataset.subscope==='guild'&&e.target.dataset.subkey==='recovery')loadRecovery();if(e.target.dataset.subscope==='payout'&&e.target.dataset.subkey==='personal')renderPersonal()});

function renderBattleRecords(){
 const runs=s.battleRuns||[];if(!runs.some(r=>r.id===battleEditing))battleEditing=runs[0]?.id||'';
 $('battleRun').innerHTML='<option value="">기록 선택</option>'+runs.map(r=>`<option value="${esc(r.id)}">${esc(battleZones[r.zone]+' · '+(r.date?r.date+' · ':'')+r.name+(r.guildRank?' · 길드 '+r.guildRank+'위':''))}</option>`).join('');$('battleRun').value=battleEditing;
 const run=runs.find(r=>r.id===battleEditing);$('battleMeta').hidden=!run||run.zone!=='normal';$('battleDate').value=run?.date||'';$('battleGuildRank').value=run?.guildRank??'';$('battleScores').innerHTML=run?s.members.map(m=>`<tr><td>${esc(m.name)}</td><td><input type="checkbox" aria-label="${esc(m.name)} 참여" data-battle-participant="${esc(m.id)}" ${(m.battleParticipation?.[run.id]||m.battleScores?.[run.id]>0)?'checked':''}></td><td><input type="number" min="0" step="any" aria-label="${esc(m.name)} 몬스터 점수 또는 기여율" data-battle-score="${esc(m.id)}" value="${m.battleScores?.[run.id]||0}"></td></tr>`).join(''):'';
 $('battleScoreHeading').textContent=run?.mode==='percent'?'딜 기여율 (%) · 합계 100':'몬스터 표시 점수 / 딜량';
}
$('battleRun').onchange=()=>{battleEditing=$('battleRun').value;renderBattleRecords();scheduleTableLayout()};
$('battleAdd').onclick=()=>{const name=$('battleName').value.trim();if(!name){alert('몬스터 이름·회차를 입력하세요.');return}s.battleRuns??=[];battleEditing=uid();s.battleRuns.push({id:battleEditing,name,zone:$('battleZone').value,mode:$('battleMode').value});$('battleName').value='';renderInputs()};
document.addEventListener('change',e=>{const id=e.target.dataset.battleScore||e.target.dataset.battleParticipant;if(!id)return;const m=s.members.find(m=>m.id===id);if(!m||!battleEditing)return;if(e.target.dataset.battleScore){m.battleScores??={};m.battleScores[battleEditing]=Number(e.target.value)}else{m.battleParticipation??={};m.battleParticipation[battleEditing]=e.target.checked;}update()});

for(const id of ['battleDate','battleGuildRank'])$(id).onchange=()=>{const run=(s.battleRuns||[]).find(r=>r.id===battleEditing);if(!run||run.zone!=='normal')return;const value=$(id).value;if(id==='battleGuildRank'){const rank=value===''?null:Number(value);if(rank!==null&&(!Number.isSafeInteger(rank)||rank<1)){alert('길드 순위는 1 이상의 정수로 입력하세요.');renderBattleRecords();return}run.guildRank=rank;}else run.date=value;renderBattleRecords();update()};

document.addEventListener('click',async e=>{const id=e.target.dataset.saveCatalogPrice;if(!id||!platformAdmin)return;const row=e.target.closest('tr'),input=row.querySelector('[data-catalog-price]'),entry=catalog.find(p=>p.item_id===id),price=Number(input.value);if(!entry||!Number.isSafeInteger(price)||price<1){$('priceStatus').textContent='시세는 1 이상의 정수로 입력하세요.';alert('시세는 1 이상의 정수로 입력하세요.');return}e.target.disabled=true;try{const response=await fetch('/api/prices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recordId:uid(),items:[{id,name:entry.item_name,price}],note:'관리자 시세표 직접 수정'})}),data=await apiJSON(response);if(!response.ok)throw Error(data.error);if(!await loadPrices())throw Error('가격은 저장됐지만 새로고침에 실패했습니다.');$('priceStatus').textContent='시세 저장 완료 · 상자 기댓값 재계산 완료';}catch(err){$('priceStatus').textContent=err.message;alert(err.message)}finally{e.target.disabled=false}});

$('priceAdminLogin').onclick=()=>{if(pending||saving){alert('DB 저장 완료 후 관리자 인증을 진행하세요.');return}showGateway();$('localRole').value='admin';$('workspaceStatus').textContent='서비스 관리자 비밀번호로 인증하면 공용 시세를 수정할 수 있습니다.';$('workspacePassword').focus();};

if(typeof ResizeObserver!=='undefined'){const chromeObserver=new ResizeObserver(()=>scheduleTableLayout());for(const el of [document.querySelector('header'),$('systemControls')])if(el)chromeObserver.observe(el);}
